SQL_DOC.P_SQL:
SELECT nvl(trim(PRDT.PLANT),'10') AS PLANT ,IVHD.LEGACY_IV_SERIAL AS LEGACY_IV_NO ,to_number(IVDT.INV_SEQ) AS LEGACY_IV_SEQ ,IVDT.STATUS AS STATUS ,replace(PODT.LEGACY_PO_NO,'_D',null) AS LEGACY_PO_NO ,PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ ,IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO ,IVDT.INV_QTY AS ITEM_QTY ,IVDT.INVOICE_DATE AS INV_DATE FROM ICOMIVDT IVDT, ICOMIVHD IVHD, ICOMPODT PODT, ICOMPRDT PRDT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.INV_SEQ= '$G_RS.INV_SEQ$' AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO= IVHD.INV_NO AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ UNION ALL SELECT PRDT.PLANT AS PLANT ,IVDT.LEGACY_IV_SERIAL AS LEGACY_IV_NO ,to_number(IVDT.INV_SEQ) AS LEGACY_IV_SEQ ,IVDT.STATUS AS STATUS ,replace(PODT.LEGACY_PO_NO,'_D',null) AS LEGACY_PO_NO ,PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ ,IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO ,IVDT.INV_QTY AS ITEM_QTY ,IVDT.INV_DATE AS INV_DATE FROM WMSIVDT IVDT, ICOMPODT PODT, ICOMPRDT PRDT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.INV_SEQ= '$G_RS.INV_SEQ$' AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ ORDER BY PLANT,LEGACY_IV_NO,LEGACY_IV_SEQ
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVDT SET SND_CHK = DECODE('$G_RS.STATUS$','D','Z','Y') , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; ELSE UPDATE WMSIVDT SET SND_CHK = DECODE('$G_RS.STATUS$','D','Z','Y') , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; END IF; END;
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVDT SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; END IF; END;
